sys_script_include.script:
var CreateSamValueBuilderTaskOverallHealths = Class.create();
CreateSamValueBuilderTaskOverallHealths.prototype = {
    initialize: function () {},

    createTask: function (publisherName) {
        if (!publisherName) {
            gs.info("❌ No publisher name provided.");
            return "Error: Publisher name is required.";
        }

        // Fetch sys_property data
        var sysPropValue = gs.getProperty("customwalk.properties");

        if (!sysPropValue) {
            gs.info("❌ System Property 'customwalk.properties' not found.");
            return "System Property not found.";
        }

        var taskInfo;
        try {
            taskInfo = JSON.parse(sysPropValue);
        } catch (e) {
            gs.error("❌ Error parsing JSON from sys_property: " + e);
            return "Error parsing system property.";
        }

        var task = new GlideRecord('samp_sp_vb_task'); // ✅ Change to your target task table
        var found = false;

        // Loop through sys_property JSON to find matching tasks
        for (var i = 0; i < taskInfo.length; i++) {
            var key = Object.keys(taskInfo[i])[0];
            var shortDesc = taskInfo[i][key].short_description.trim() + " - " + publisherName;

            // Check if the task already exists
            task.initialize();
            task.addQuery("short_description", shortDesc);
            task.query();

            if (task.next()) {
                // Task already exists, update it
                task.description = taskInfo[i][key].description;
                task.work_notes = taskInfo[i][key].instruction;
                task.state = "1"; // Keep it open
                task.update();

                gs.info("🔄 Task updated in samp_sp_vb_task for Publisher: " + publisherName + " - " + key);
                found = true;
            } else {
                // Task does not exist, create a new one
                task.initialize();
                task.short_description = shortDesc;
                task.description = taskInfo[i][key].description;
                task.work_notes = taskInfo[i][key].instruction;
                task.state = "1"; // Open
                task.insert();

                gs.info("✅ Task created in samp_sp_vb_task for Publisher: " + publisherName + " - " + key);
                found = true;
            }
        }

        return found ? "✅ Tasks processed successfully for " + publisherName : "❌ No matching tasks found.";
    },

    type: 'CreateSamValueBuilderTaskOverallHealths'
};
